// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user) public {
        vm.assume(user != address(0));
        // Initially, wards[user] should be 0
        assertTrue(c.wards(user) == 0);
        // Now call rely(user), then check wards[user] == 1
        c.rely(user);
        assertTrue(c.wards(user) == 1);
        // Now call deny(user), then check wards[user] == 0 (this fails on mutant)
        c.deny(user);
        assertTrue(c.wards(user) == 0);
    }
}

